	// its half of the connection, and the system is waiting to be sure that the remote peer
	// received the last acknowledgement.
	NetworkConnectionQueryStateIDTIMEWAIT = 6
	// The socket is not in use.
	NetworkConnectionQueryStateIDCLOSED = 7
	// The socket connection has been closed by the remote peer, and the system is waiting for the
	// local application to close its half of the connection.
	NetworkConnectionQueryStateIDCLOSEWAIT = 8
	// The socket connection has been closed by the remote peer, the local application has closed
	// its half of the connection, and the system is waiting for the remote peer to acknowledge the
	// close.
	NetworkConnectionQueryStateIDLASTACK = 9
	// The socket is listening for incoming connections.
	NetworkConnectionQueryStateIDLISTEN = 10
	// The socket connection has been closed by the local application and the remote peer
	// simultaneously, and the remote peer has not yet acknowledged the close attempt of the local
