	ProcessQueryDispositionIDApproved = 8
	// A quarantined file or other content was restored to its original location.
	ProcessQueryDispositionIDRestored = 9
	// A suspicious or risky entity was deemed to no longer be suspicious (re-scored).
	ProcessQueryDispositionIDExonerated = 10
	// A corrupt file or configuration was corrected.
	ProcessQueryDispositionIDCorrected = 11
	// A corrupt file or configuration was partially corrected.
	ProcessQueryDispositionIDPartiallyCorrected = 12
	// A corrupt file or configuration was not corrected.
	ProcessQueryDispositionIDUncorrected = 13
	// An operation was delayed, for example if a restart was required to finish the operation.
	ProcessQueryDispositionIDDelayed = 14
	// Suspicious activity or a policy violation was detected without further action.
	ProcessQueryDispositionIDDetected = 15
	// The outcome of an operation had no action taken.
	ProcessQueryDispositionIDNoAction = 16
	// The operation or action was logged without further action.
	ProcessQueryDispositionIDLogged = 17
	// A file or other entity was marked with extended attributes.
	ProcessQueryDispositionIDTagged = 18
	// The request or activity was detected as a threat and resulted in a notification but request
	// was not blocked.
	ProcessQueryDispositionIDAlert = 19
	// Counted the request or activity but did not determine whether to allow it or block it.
	ProcessQueryDispositionIDCount = 20
	// The request was detected as a threat and resulted in the connection being reset.
	ProcessQueryDispositionIDReset = 21
	// Required the end user to solve a CAPTCHA puzzle to prove that a human being is sending the
	// request.
	ProcessQueryDispositionIDCaptcha = 22
	// Ran a silent challenge that required the client session to verify that it's a browser, and
	// not a bot.
